package com.example.starter.lc.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 开立信用证请求。
 *
 * @param requestId     幂等键
 * @param lcNo          信用证编号
 * @param applicant     开证申请人
 * @param beneficiary   受益人
 * @param currency      币种（ISO 4217），为空默认 USD
 * @param totalAmount   信用证总金额（币种元）
 * @param expiryDate    交单有效期（UTC 日期，含当日）
 */
public record CreateLcRequest(
        @NotBlank String requestId,
        @NotBlank String lcNo,
        @NotBlank String applicant,
        @NotBlank String beneficiary,
        String currency,
        @NotNull @DecimalMin("0.01") BigDecimal totalAmount,
        @NotNull LocalDate expiryDate) {
}

package com.example.starter.lc.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 交单项下单据。
 *
 * @param docType 单据类型，如 BILL_OF_LADING、COMMERCIAL_INVOICE
 * @param docRef  单据编号/标识
 */
public record DocumentItem(
        @NotBlank String docType,
        @NotBlank String docRef) {
}

package com.example.starter.lc.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 受益人交单请求；拒付后改单重交请使用新 requestId，视为新交单批次。
 *
 * @param requestId   幂等键
 * @param lcNo        信用证编号
 * @param drawAmount  本批支款金额（币种元）
 * @param presentedAt 银行收到单据时刻（UTC），为空取服务当前时间
 * @param documents   随附单据清单
 */
public record PresentDocumentsRequest(
        @NotBlank String requestId,
        @NotBlank String lcNo,
        @NotNull @DecimalMin("0.01") BigDecimal drawAmount,
        Instant presentedAt,
        @NotEmpty @Valid List<DocumentItem> documents) {
}

package com.example.starter.lc.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 不符点条目，按单据类型归类。
 *
 * @param docType     不符点对应单据类型
 * @param description 不符点描述
 */
public record DiscrepancyItem(
        @NotBlank String docType,
        @NotBlank String description) {
}

package com.example.starter.lc.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.time.Instant;
import java.util.List;

/**
 * 银行拒付通知请求：必须一次性列明全部不符点，事后不得补充。
 *
 * @param requestId    幂等键
 * @param batchNo      交单批次号
 * @param refusedAt    拒付通知发出时刻（UTC），为空取服务当前时间；晚于截止时刻则拒付无效
 * @param discrepancies 全部不符点清单（至少一条）
 */
public record RefuseRequest(
        @NotBlank String requestId,
        @NotBlank String batchNo,
        Instant refusedAt,
        @NotEmpty @Valid List<DiscrepancyItem> discrepancies) {
}

package com.example.starter.lc.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.time.Instant;
import java.util.List;

/**
 * 开证申请人放弃不符点声明；声明必须覆盖全部已列不符点，部分放弃无效。
 *
 * @param requestId     幂等键
 * @param batchNo       交单批次号
 * @param applicant     声明放弃的开证申请人（须与信用证申请人一致）
 * @param waivedAt      声明时刻（UTC），为空取服务当前时间
 * @param discrepancies 声明放弃的不符点清单（须与拒付通知所列完全一致）
 */
public record WaiveDiscrepanciesRequest(
        @NotBlank String requestId,
